    def _finalize_parsed_value(
        value: JSONReturnType,
        repairer: "SchemaRepairer | None",
        schema: dict[str, Any] | bool | None,
        path: str,
    ) -> JSONReturnType:
        if repairer is None:
            return value
        return repairer.repair_value(value, schema, path)

