    first = self.json_str[i]
    if first != ")":
        first_lower = first.lower()
        is_literal = False
        for literal in ("true", "false", "null"):
            end = i + len(literal)
            if self.json_str[i:end].lower() == literal and (
                end >= length or self.json_str[end] in ",)]} \t\r\n"
            ):
                is_literal = True
                break
        if not (
            first in "[{("
            or first in STRING_DELIMITERS
            or first.isdigit()
            or first in "-."
            or is_literal
