def descend(
    self,
    instance,
    schema,
    path=None,
    schema_path=None,
    resolver=None,
):
    if schema is True:
        return
    elif schema is False:
        yield exceptions.ValidationError(
            f"False schema does not allow {instance!r}",
            validator=None,
            validator_value=None,
            instance=instance,
            schema=schema,
        )
        return

    if self._ref_resolver is not None:
        evolved = self.evolve(schema=schema)
    else:
        if resolver is None:
            resolver = self._resolver.in_subresource(
                specification.create_resource(schema),
            )
        evolved = self.evolve(schema=schema, _resolver=resolver)

    for k, v in applicable_validators(schema):
        validator = evolved.VALIDATORS.get(k)
        if validator is None:
            continue

        errors = validator(evolved, v, instance, schema) or ()
        for error in errors:
            # set details if not already set by the called fn
            error._set(
                validator=k,
                validator_value=v,
                instance=instance,
                schema=schema,
                type_checker=evolved.TYPE_CHECKER,
            )
            if k not in {"if", "$ref"}:
                error.schema_path.appendleft(k)
            if path is not None:
                error.path.appendleft(path)
            if schema_path is not None:
                error.schema_path.appendleft(schema_path)
            yield error

def iter_errors(self, instance, _schema=None):
    if _schema is not None:
        warnings.warn(
            (
                "Passing a schema to Validator.iter_errors "
                "is deprecated and will be removed in a future "
                "release. Call validator.evolve(schema=new_schema)."
                "iter_errors(...) instead."
            ),
            DeprecationWarning,
            stacklevel=2,
        )
        validators = [
            (self.VALIDATORS[k], k, v)
            for k, v in applicable_validators(_schema)
            if k in self.VALIDATORS
        ]
    else:
        _schema, validators = self.schema, self._validators

    if _schema is True:
        return
    elif _schema is False:
        yield exceptions.ValidationError(
            f"False schema does not allow {instance!r}",
            validator=None,
            validator_value=None,
            instance=instance,
            schema=_schema,
        )
        return

    for validator, k, v in validators:
        errors = validator(self, v, instance, _schema) or ()
        for error in errors:
            # set details if not already set by the called fn
            error._set(
                validator=k,
                validator_value=v,
                instance=instance,
                schema=_schema,
                type_checker=self.TYPE_CHECKER,
            )
            if k not in {"if", "$ref"}:
