def _iter_validation_errors(self, value: JSONReturnType, schema: dict[str, Any]) -> Any:
    if schema is self.root_schema:
        return self._get_validator(schema).iter_errors(value)
    # Validate subschemas as part of the original root document so root-relative
    # references such as #/$defs/Item remain resolvable.
    prepared_schema = self._prepare_schema_for_validation(schema)
    return self._get_root_validator().descend(value, prepared_schema)

